  padding: 20px;
  margin: -13px;
  border: 1px solid #1A97D8;
  border-radius: 4px;
}

.s_ellips {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  display: block;
}

.d_start {
  display: flex;
  justify-content: flex-start
}

